package com.nexus.access.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import org.junit.jupiter.api.Test; import com.nexus.access.backend.user.User;
class RefreshTokenServiceTest { @Test void issuesOnlyHashAndRevokesOnConsume(){RefreshTokenRepository repo=mock(RefreshTokenRepository.class);RefreshTokenService service=new RefreshTokenService(repo,60);User user=new User();String raw=service.issue(user);var c=org.mockito.ArgumentCaptor.forClass(RefreshToken.class);verify(repo).save(c.capture());assertNotEquals(raw,c.getValue().getTokenHash());when(repo.findByTokenHash(c.getValue().getTokenHash())).thenReturn(java.util.Optional.of(c.getValue()));assertSame(user,service.consume(raw));assertNotNull(c.getValue().getRevokedAt());}}
